import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTeachers() {
  const [teachers, setTeachers] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  
  const [formData, setFormData] = useState({ 
    name: '', username: '', subject: 'Mathematics', qualifications: '', 
    email: '', phone_number: '', address: '', password: 'TC@123' 
  });
  
  const [searchQuery, setSearchQuery] = useState('');

  // Dropdown එකට අවශ්‍ය විෂයයන් ලැයිස්තුව
  const availableSubjects = ['Mathematics', 'Science', 'English', 'Sinhala', 'ICT', 'Accounting', 'Business Studies', 'Dancing', 'History'];

  const fetchTeachers = () => axios.get('http://localhost:8081/api/view-teachers').then(res => setTeachers(res.data));
  useEffect(() => { fetchTeachers(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (isEditing) {
      // මෙතන API link එක /api/edit-teacher විදියට නිවැරදි කළා
      axios.put(`http://localhost:8081/api/edit-teacher/${editId}`, formData)
        .then(() => { fetchTeachers(); resetForm(); alert("Teacher Updated Successfully!"); })
        .catch(err => alert("Error updating teacher"));
    } else {
      axios.post('http://localhost:8081/api/add-teacher', formData)
        .then(() => { fetchTeachers(); resetForm(); alert("Teacher Added Successfully!"); })
        .catch(err => alert("Error adding teacher"));
    }
  };

  const handleDelete = (id) => { 
    if(window.confirm("Are you sure you want to delete this teacher?")) 
      axios.delete(`http://localhost:8081/api/delete-teacher/${id}`).then(() => fetchTeachers()); 
  };

  const handleEdit = (t) => {
    setIsEditing(true); setEditId(t.id);
    setFormData({ 
      name: t.name, 
      username: t.username || '', 
      subject: t.subject || 'Mathematics', // හිස් නම් default එකක් දෙනවා
      qualifications: t.qualifications || '', 
      email: t.email || '', 
      phone_number: t.phone_number, 
      address: t.address || '', 
      password: t.password || 'TC@123'
    });
    setShowForm(true);
  };

  const resetForm = () => { 
    setShowForm(false); setIsEditing(false); setEditId(null); 
    setFormData({ name: '', username: '', subject: 'Mathematics', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' }); 
  };

  const filteredTeachers = [...teachers].sort((a, b) => b.id - a.id).filter(t => t.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div style={{ padding: '10px', fontFamily: 'sans-serif', animation: 'fadeIn 0.5s' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px', backgroundColor: '#fff', padding: '15px 20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.02)' }}>
        <h2 style={{ margin: 0, color: '#1e293b' }}>🧑‍🏫 Manage Teachers</h2>
        <div style={{ display: 'flex', gap: '15px' }}>
          <input type="text" placeholder="Search Teachers..." onChange={(e) => setSearchQuery(e.target.value)} style={{ padding: '8px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none' }} />
          <button onClick={() => { resetForm(); setShowForm(true); }} style={{ padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>+ Add Teacher</button>
        </div>
      </div>

      <div style={{ backgroundColor: '#fff', borderRadius: '12px', overflowX: 'auto', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '1000px' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={thStyle}>Name</th>
              <th style={thStyle}>Username</th>
              <th style={thStyle}>Subject</th>
              <th style={thStyle}>Qualifications</th>
              <th style={thStyle}>Telephone</th>
              <th style={thStyle}>Email</th>
              <th style={thStyle}>Address</th>
              <th style={{...thStyle, textAlign: 'center'}}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredTeachers.length > 0 ? filteredTeachers.map((t, index) => (
              <tr key={t.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{...tdStyle, color: '#15803d', fontWeight: 'bold'}}>{t.name}</td>
                <td style={{...tdStyle, color: '#475569'}}>{t.username || '-'}</td>
                <td style={{...tdStyle, fontWeight: 'bold'}}>{t.subject || '-'}</td>
                <td style={tdStyle}>{t.qualifications || '-'}</td>
                <td style={tdStyle}>{t.phone_number}</td>
                <td style={tdStyle}>{t.email || '-'}</td>
                <td style={{...tdStyle, color: '#64748b'}}>{t.address || '-'}</td>
                <td style={{...tdStyle, textAlign: 'center'}}>
                  <button onClick={() => handleEdit(t)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: '16px', marginRight: '10px' }}>✏️</button>
                  <button onClick={() => handleDelete(t.id)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: '16px' }}>🗑️</button>
                </td>
              </tr>
            )) : <tr><td colSpan="8" style={{ padding: '30px', textAlign: 'center', color: '#94a3b8' }}>No teachers found.</td></tr>}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '500px', maxHeight: '90vh', overflowY: 'auto', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' }}>
            <h3 style={{ margin: '0 0 20px 0', borderBottom: '1px solid #f1f5f9', paddingBottom: '10px', color: '#1e293b' }}>{isEditing ? '✏️ Edit Teacher' : '➕ Add Teacher'}</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <input type="text" placeholder="Full Name" value={formData.name} onChange={(e)=>setFormData({...formData, name: e.target.value})} required style={inputStyle} />
              <input type="text" placeholder="Username (For Login)" value={formData.username} onChange={(e)=>setFormData({...formData, username: e.target.value})} required style={inputStyle} />
              
              {/* Subject එක ටයිප් කරනවා වෙනුවට Dropdown එකක් දැම්මා */}
              <select value={formData.subject} onChange={(e)=>setFormData({...formData, subject: e.target.value})} style={inputStyle} required>
                {availableSubjects.map(sub => <option key={sub} value={sub}>{sub}</option>)}
              </select>

              <input type="text" placeholder="Qualifications (e.g. B.Sc, Diploma)" value={formData.qualifications} onChange={(e)=>setFormData({...formData, qualifications: e.target.value})} style={inputStyle} />
              <input type="text" placeholder="Telephone" value={formData.phone_number} onChange={(e)=>setFormData({...formData, phone_number: e.target.value})} required style={inputStyle} />
              <input type="email" placeholder="Email" value={formData.email} onChange={(e)=>setFormData({...formData, email: e.target.value})} style={inputStyle} />
              <input type="text" placeholder="Address" value={formData.address} onChange={(e)=>setFormData({...formData, address: e.target.value})} style={inputStyle} />
              
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '10px' }}>
                <button type="button" onClick={resetForm} style={{ padding: '10px 20px', borderRadius: '8px', border: 'none', backgroundColor: '#f1f5f9', color: '#475569', cursor: 'pointer', fontWeight: 'bold' }}>Cancel</button>
                <button type="submit" style={{ padding: '10px 25px', backgroundColor: isEditing ? '#3b82f6' : '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>{isEditing ? 'Update' : 'Save'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const inputStyle = { padding: '10px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', width: '100%', boxSizing: 'border-box', outline: 'none', fontSize: '14px' };
const thStyle = { padding: '12px 15px', fontSize: '13px', textAlign: 'left', color: '#475569', whiteSpace: 'nowrap' };
const tdStyle = { padding: '12px 15px', fontSize: '14px', borderBottom: '1px solid #f1f5f9' };
